:root {
  --ink: #1a1a1a;
  --muted: #666666;
  --accent: #0066cc;
  --warm: #e6f0ff;
  --line: #e0e0e0;
  --paper: #ffffff;
  --code-bg: #f5f5f5;
  --highlight: #fff4e5;
}

.chapter-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.6;
  padding: 20px;
  max-width: 800px;
  margin: 0 auto;
  box-sizing: border-box;
}

.chapter-header {
  border-bottom: 2px solid var(--ink);
  margin-bottom: 30px;
  padding-bottom: 10px;
}

.chapter-title {
  font-size: 24px;
  font-weight: 700;
  margin: 0 0 10px 0;
  color: var(--ink);
}

.chapter-takeaway {
  font-size: 16px;
  color: var(--muted);
  margin: 0;
  font-style: italic;
}

.node-block {
  margin-bottom: 40px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 20px;
  background: #fff;
}

.node-title {
  font-size: 20px;
  font-weight: 600;
  margin-top: 0;
  margin-bottom: 15px;
  color: var(--accent);
  border-left: 4px solid var(--accent);
  padding-left: 10px;
}

.node-summary {
  font-size: 15px;
  margin-bottom: 20px;
  color: var(--ink);
}

/* Stepper Styles */
.interactive-stepper {
  background: var(--warm);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 20px;
  margin: 20px 0;
}

.stepper-controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 15px;
  margin-bottom: 20px;
}

.control-btn {
  background: var(--paper);
  border: 1px solid var(--accent);
  color: var(--accent);
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  transition: all 0.2s;
}

.control-btn:hover {
  background: var(--accent);
  color: var(--paper);
}

.control-btn.secondary {
  border-color: var(--muted);
  color: var(--muted);
}

.control-btn.secondary:hover {
  background: var(--muted);
  color: var(--paper);
}

.step-label {
  font-weight: 600;
  font-size: 14px;
  color: var(--ink);
  min-width: 80px;
  text-align: center;
}

.stepper-visual {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.flow-diagram {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: 100%;
  max-width: 300px;
}

.flow-node {
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 6px;
  padding: 10px;
  width: 100%;
  text-align: center;
  transition: all 0.3s ease;
  opacity: 0.6;
  transform: scale(0.98);
}

.flow-node.active {
  border-color: var(--accent);
  background: #fff;
  opacity: 1;
  transform: scale(1.02);
  box-shadow: 0 4px 12px rgba(0, 102, 204, 0.15);
  z-index: 2;
}

.flow-node input-node,
.flow-node output-node {
  background: var(--code-bg);
  border-style: dashed;
  opacity: 1;
  transform: scale(1);
}

.flow-arrow {
  color: var(--muted);
  font-size: 18px;
  font-weight: bold;
  opacity: 0.5;
  transition: opacity 0.3s;
}

.flow-arrow.active {
  opacity: 1;
  color: var(--accent);
}

.label {
  display: block;
  font-weight: 600;
  font-size: 14px;
  margin-bottom: 4px;
}

.detail {
  display: block;
  font-size: 12px;
  color: var(--muted);
  font-family: monospace;
}

.formula-preview {
  display: block;
  font-family: "Times New Roman", Times, serif;
  font-style: italic;
  font-size: 14px;
  color: var(--ink);
  background: var(--code-bg);
  padding: 2px 6px;
  border-radius: 4px;
  margin-top: 4px;
}

.dimension-tag {
  display: inline-block;
  font-size: 11px;
  background: var(--ink);
  color: var(--paper);
  padding: 2px 6px;
  border-radius: 10px;
  margin-top: 6px;
  font-family: monospace;
}

.stepper-explanation {
  margin-top: 25px;
  padding: 15px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 6px;
  width: 100%;
  box-sizing: border-box;
}

.stepper-explanation h3 {
  margin: 0 0 10px 0;
  font-size: 16px;
  color: var(--accent);
}

.stepper-explanation p {
  margin: 0;
  font-size: 14px;
  color: var(--ink);
}

/* Formula Card */
.formula-card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 20px;
  margin: 20px 0;
}

.formula-display {
  font-family: "Times New Roman", Times, serif;
  font-size: 20px;
  text-align: center;
  padding: 15px;
  background: var(--code-bg);
  border-radius: 4px;
  margin-bottom: 20px;
  color: var(--ink);
}

.formula-conditions h4 {
  font-size: 15px;
  margin: 0 0 10px 0;
  color: var(--ink);
}

.condition-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.condition-list li {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
}

.condition-list li:last-child {
  border-bottom: none;
}

.condition-label {
  color: var(--muted);
  font-weight: 500;
}

.condition-value {
  color: var(--ink);
  font-family: monospace;
  font-weight: 600;
}

/* Teaching Note */
.teaching-note {
  background: #fff8e1;
  border-left: 4px solid #ffc107;
  padding: 15px;
  margin: 20px 0;
  font-size: 14px;
  color: #5d4037;
}

.teaching-note h4 {
  margin: 0 0 10px 0;
  font-size: 15px;
}

.teaching-note ul {
  margin: 0;
  padding-left: 20px;
}

.teaching-note li {
  margin-bottom: 5px;
}

/* Source Button */
.source-block {
  margin-top: 20px;
  text-align: right;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 6px 12px;
  font-size: 12px;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--ink);
  color: var(--ink);
  background: var(--code-bg);
}

/* Responsive */
@media (max-width: 480px) {
  .chapter-container {
    padding: 10px;
  }

  .node-block {
    padding: 15px;
  }

  .formula-display {
    font-size: 16px;
    overflow-x: auto;
  }

  .condition-list li {
    flex-direction: column;
    gap: 4px;
  }
}
