(function() {
  'use strict';

  // State Management
  const state = {
    currentStep: 1,
    totalSteps: 4,
    stepData: [
      {
        title: "步骤 1：多头自注意力处理",
        desc: "输入向量 $x$ 首先进入第一个子层，即多头自注意力机制。该机制允许模型在不同表示子空间中关注不同位置的信息。",
        activeNodes: ['sublayer-node'],
        activeArrows: ['arrow-1']
      },
      {
        title: "步骤 2：残差连接与归一化",
        desc: "自注意力层的输出与原始输入 $x$ 相加（残差连接），然后结果通过层归一化函数 LayerNorm 进行处理，得到第一阶段的输出。",
        activeNodes: ['residual-node', 'norm-node'],
        activeArrows: ['arrow-2', 'arrow-3']
      },
      {
        title: "步骤 3：前馈网络处理",
        desc: "上一阶段的输出进入第二个子层，即逐点全连接前馈网络。该网络独立地应用于每个位置。",
        activeNodes: ['ffn-node'],
        activeArrows: ['arrow-4']
      },
      {
        title: "步骤 4：再次残差连接与归一化",
        desc: "前馈网络的输出再次与该层的输入（即步骤 2 的输出）相加，并通过 LayerNorm，完成整个编码器层的计算。",
        activeNodes: ['residual-node', 'norm-node'],
        activeArrows: ['arrow-5', 'arrow-6'],
        // Special handling for second residual/norm visually if needed, 
        // but for simplicity in this DOM structure, we highlight the generic nodes again
        // or we could have duplicated IDs. Given the static HTML, we highlight the bottom ones.
        // To fix ambiguity in static HTML with duplicate classes, we rely on CSS nth-child or specific logic.
        // However, the provided HTML has unique IDs for arrows but shared classes for nodes.
        // Let's refine the selector logic in the update function.
      }
    ]
  };

  // DOM Elements
  const els = {
    prev: document.getElementById('step-prev'),
    next: document.getElementById('step-next'),
    reset: document.getElementById('step-reset'),
    indicator: document.getElementById('step-indicator'),
    title: document.getElementById('step-title'),
    desc: document.getElementById('step-desc'),
    nodes: document.querySelectorAll('.flow-node'),
    arrows: document.querySelectorAll('.flow-arrow')
  };

  // Helper: Clear Active States
  function clearActive() {
    els.nodes.forEach(n => n.classList.remove('active'));
    els.arrows.forEach(a => a.classList.remove('active'));
  }

  // Helper: Update Visuals
  function updateVisuals() {
    clearActive();
    const step = state.stepData[state.currentStep - 1];

    // Update Text
    els.title.textContent = step.title;
    els.desc.textContent = step.desc;
    els.indicator.textContent = `步骤 ${state.currentStep} / ${state.totalSteps}`;

    // Highlight Arrows
    step.activeArrows.forEach(id => {
      const arrow = document.getElementById(id);
      if (arrow) arrow.classList.add('active');
    });

    // Highlight Nodes
    // Note: For steps 2 and 4, we need to be careful which nodes to highlight 
    // since the HTML has generic classes. 
    // Step 2 highlights the first residual/norm set.
    // Step 4 highlights the second residual/norm set.
    // We can use DOM order or specific data attributes if we had them.
    // Since the HTML structure is linear:
    // Index 0: Input
    // Index 1: Attn (Step 1)
    // Index 2: Residual 1 (Step 2)
    // Index 3: Norm 1 (Step 2)
    // Index 4: FFN (Step 3)
    // Index 5: Residual 2 (Step 4)
    // Index 6: Norm 2 (Step 4)
    // Index 7: Output

    const nodeArray = Array.from(els.nodes);

    if (state.currentStep === 1) {
      nodeArray[1].classList.add('active'); // Attn
    } else if (state.currentStep === 2) {
      nodeArray[2].classList.add('active'); // Residual 1
      nodeArray[3].classList.add('active'); // Norm 1
    } else if (state.currentStep === 3) {
      nodeArray[4].classList.add('active'); // FFN
    } else if (state.currentStep === 4) {
      nodeArray[5].classList.add('active'); // Residual 2
      nodeArray[6].classList.add('active'); // Norm 2
    }

    // Always keep input/output visible but not 'active' in the sense of processing
    nodeArray[0].classList.add('active'); 
    nodeArray[7].classList.add('active');
  }

  // Event Handlers
  function handleNext() {
    if (state.currentStep < state.totalSteps) {
      state.currentStep++;
      updateVisuals();
    }
  }

  function handlePrev() {
    if (state.currentStep > 1) {
      state.currentStep--;
      updateVisuals();
    }
  }

  function handleReset() {
    state.currentStep = 1;
    updateVisuals();
  }

  // Source Button Handling (Mock Kernel Bridge)
  function handleSourceClick(e) {
    const btn = e.currentTarget;
    const sourceId = btn.getAttribute('data-source');
    const nodeId = btn.getAttribute('data-node');
    // In a real kernel, this would trigger a navigation or modal.
    // Here we just log or visually acknowledge.
    console.log(`Source requested: ${sourceId} for node ${nodeId}`);
    // Visual feedback
    const originalText = btn.textContent;
    btn.textContent = "查阅中...";
    setTimeout(() => {
      btn.textContent = originalText;
    }, 1000);
  }

  // Initialization
  function init() {
    // Bind Events
    els.next.addEventListener('click', handleNext);
    els.prev.addEventListener('click', handlePrev);
    els.reset.addEventListener('click', handleReset);

    const sourceBtns = document.querySelectorAll('.source-btn');
    sourceBtns.forEach(btn => {
      btn.addEventListener('click', handleSourceClick);
    });

    // Initial Render
    updateVisuals();
  }

  // Run
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
